  1→import React, { useState, useCallback, useEffect } from "react";
  2→import { useAuth } from "@/hooks/useAuth";
  3→import { supabase } from "@/integrations/supabase/client";
  4→import AppHeader from "@/components/AppHeader";
  5→import AuthDialog from "@/components/AuthDialog";
  6→import JobSidebar from "@/components/JobSidebar";
  7→import JobDetailView from "@/components/JobDetailView";
  8→import { SidebarProvider, SidebarTrigger, SidebarInset } from "@/components/ui/sidebar";
  9→import { toast } from "sonner";
 10→
 11→export interface PastJob {
 12→  id: string;
 13→  title: string | null;
 14→  job_description: string;
 15→  status: string;
 16→  created_at: string;
 17→  resume_count: number;
 18→  jd_analysis_json: any;
 19→  dynamic_weights_json: Record<string, number> | null;
 20→  inbox_email: string | null;
 21→}
 22→
 23→export interface Result {
 24→  id: string;
 25→  resume_id: string;
 26→  overall_score: number;
 27→  missing_skills: string[];
 28→  summary: string | null;
 29→  interview_questions: any;
 30→  filename: string;
 31→  file_path: string | null;
 32→  candidate_name: string | null;
 33→  candidate_email?: string | null;
 34→  candidate_phone?: string | null;
 35→  candidate_location?: string | null;
 36→  // Dynamic scoring fields
 37→  hard_fit?: boolean;
 38→  category_scores_json?: Record<string, { score: number; evidence?: any[]; notes?: string }>;
 39→  confidence?: number;
 40→  strengths_json?: string[];
 41→  gaps_json?: string[];
 42→  explanation_json?: { summary?: string; why_ranked_here?: string; key_tradeoffs?: string };
 43→  matched_must_haves?: string[];
 44→  missing_must_haves?: string[];
 45→  scoring_version?: string;
 46→  pending?: boolean;
 47→  parsed_json?: any;
 48→}
 49→
 50→export interface ExistingResume {
 51→  id: string;
 52→  filename: string;
 53→  file_path: string | null;
 54→  candidate_name: string | null;
 55→  created_at: string;
 56→}
 57→
 58→const Index = () => {
 59→  const { user } = useAuth();
 60→
 61→  const [pastJobs, setPastJobs] = useState<PastJob[]>([]);
 62→  const [selectedJobId, setSelectedJobId] = useState<string | null>(null);
 63→  const [loadingPastJobs, setLoadingPastJobs] = useState(false);
 64→  const [results, setResults] = useState<Result[]>([]);
 65→  const [existingResumes, setExistingResumes] = useState<ExistingResume[]>([]);
 66→  const [authOpen, setAuthOpen] = useState(false);
 67→
 68→  const selectedJob = pastJobs.find((j) => j.id === selectedJobId) ?? null;
 69→
 70→  const fetchPastJobs = useCallback(async () => {
 71→    if (!user) return;
 72→    setLoadingPastJobs(true);
 73→    try {
 74→      const { data: jobs } = await supabase
 75→        .from("jobs")
 76→        .select("id, title, job_description, status, created_at, jd_analysis_json, dynamic_weights_json, inbox_email, resumes(count)")
 77→        .eq("user_id", user.id)
 78→        .order("created_at", { ascending: false })
 79→        .limit(50);
 80→      if (jobs) {
 81→        setPastJobs(jobs.map((j: any) => ({
 82→          id: j.id,
 83→          title: j.title,
 84→          job_description: j.job_description,
 85→          status: j.status,
 86→          created_at: j.created_at,
 87→          resume_count: j.resumes?.[0]?.count ?? 0,
 88→          jd_analysis_json: j.jd_analysis_json,
 89→          dynamic_weights_json: j.dynamic_weights_json,
 90→          inbox_email: j.inbox_email ?? null,
 91→        })));
 92→      }
 93→    } catch (err) {
 94→      console.error("Failed to load past jobs:", err);
 95→    } finally {
 96→      setLoadingPastJobs(false);
 97→    }
 98→  }, [user]);
 99→
100→  useEffect(() => {
101→    fetchPastJobs();
102→  }, [fetchPastJobs]);
103→
104→  const loadJobData = async (jobId: string) => {
105→    setSelectedJobId(jobId);
106→    try {
107→      const [resumesRes, resumeListRes] = await Promise.all([
108→        supabase
109→          .from("resumes")
110→          .select("id, filename, file_path, candidate_name, created_at")
111→          .eq("job_id", jobId)
112→          .order("created_at", { ascending: false }),
113→        supabase
114→          .from("resumes")
115→          .select("id, filename, file_path, candidate_name, parsed_json")
116→          .eq("job_id", jobId),
117→      ]);
118→
119→      const resumes = resumesRes.data ?? [];
120→      setExistingResumes(resumes);
121→
122→      const resumeData = (resumeListRes.data ?? []) as Array<{
123→        id: string;
124→        filename: string;
125→        file_path: string | null;
126→        candidate_name: string | null;
127→        parsed_json?: any;
128→      }>;
129→      if (resumeData.length === 0) {
130→        setResults([]);
131→        return;
132→      }
133→
134→      const resumeIds = resumeData.map((r) => r.id);
135→      const { data: resultData } = await supabase
136→        .from("results")
137→        .select("id, resume_id, overall_score, missing_skills, summary, interview_questions, hard_fit, category_scores_json, confidence, strengths_json, gaps_json, explanation_json, matched_must_haves, missing_must_haves, scoring_version")
138→        .in("resume_id", resumeIds);
139→
140→      const resumeMap = new Map(resumeData.map((r) => [r.id, r]));
141→      const merged: Result[] = (resultData ?? []).map((r: any) => {
142→        const resume = resumeMap.get(r.resume_id);
143→        const parsed = resume?.parsed_json as any;
144→        return {
145→          ...r,
146→          overall_score: r.overall_score ?? 0,
147→          missing_skills: r.missing_skills ?? [],
148→          filename: resume?.filename ?? "Unknown",
149→          file_path: resume?.file_path ?? null,
150→          candidate_name: resume?.candidate_name ?? null,
151→          candidate_email: parsed?.email ?? parsed?.contact?.email ?? null,
152→          candidate_phone: parsed?.phone ?? parsed?.contact?.phone ?? null,
153→          candidate_location: parsed?.location ?? parsed?.contact?.location ?? null,
154→          parsed_json: resume?.parsed_json ?? null,
155→        };
156→      });
157→      merged.sort((a, b) => b.overall_score - a.overall_score);
158→      setResults(merged);
159→    } catch (err) {
160→      console.error("Failed to load job data:", err);
161→      toast.error("Failed to load job data");
162→    }
163→  };
164→
165→  const handleNewJob = () => {
166→    setSelectedJobId(null);
167→    setResults([]);
168→    setExistingResumes([]);
169→  };
170→
171→  const handleJobCreated = (job: PastJob) => {
172→    setPastJobs((prev) => [job, ...prev]);
173→    setSelectedJobId(job.id);
174→    loadJobData(job.id);
175→  };
176→
177→  const handleRenameJob = (jobId: string, newTitle: string) => {
178→    setPastJobs((prev) =>
179→      prev.map((j) => (j.id === jobId ? { ...j, title: newTitle } : j))
180→    );
181→  };
182→
183→  const handleDeleteJob = async (jobId: string) => {
184→    try {
185→      await supabase.from("resumes").delete().eq("job_id", jobId);
186→      await supabase.from("jobs").delete().eq("id", jobId);
187→      setPastJobs((prev) => prev.filter((j) => j.id !== jobId));
188→      if (selectedJobId === jobId) handleNewJob();
189→      toast.success("Job deleted");
190→    } catch {
191→      toast.error("Failed to delete job");
192→    }
193→  };
194→
195→  const handleJobUpdated = (jobId: string, updates: Partial<PastJob>) => {
196→    setPastJobs((prev) =>
197→      prev.map((j) => (j.id === jobId ? { ...j, ...updates } : j))
198→    );
199→  };
200→
201→  const requireAuth = useCallback(() => {
202→    if (!user) { setAuthOpen(true); return true; }
203→    return false;
204→  }, [user]);
205→
206→  return (
207→    <SidebarProvider className="h-svh overflow-hidden">
208→      <JobSidebar
209→        pastJobs={pastJobs}
210→        selectedJobId={selectedJobId}
211→        loadingPastJobs={loadingPastJobs}
212→        onSelectJob={loadJobData}
213→        onNewJob={handleNewJob}
214→        onRenameJob={handleRenameJob}
215→        onDeleteJob={handleDeleteJob}
216→        onAuthRequired={() => setAuthOpen(true)}
217→        isAuthenticated={!!user}
218→      />
219→
220→      <SidebarInset className="h-svh overflow-y-auto">
221→        <AppHeader />
222→        <div className="flex items-center h-10 px-4 border-b border-border md:hidden">
223→          <SidebarTrigger />
224→          <span className="ml-2 text-sm font-medium text-muted-foreground">Job History</span>
225→        </div>
226→        <JobDetailView
227→          selectedJobId={selectedJobId}
228→          selectedJob={selectedJob}
229→          results={results}
230→          setResults={setResults}
231→          existingResumes={existingResumes}
232→          setExistingResumes={setExistingResumes}
233→          onJobCreated={handleJobCreated}
234→          onAuthRequired={() => setAuthOpen(true)}
235→          isAuthenticated={!!user}
236→          onJobUpdated={handleJobUpdated}
237→        />
238→      </SidebarInset>
239→
240→      <AuthDialog open={authOpen} onOpenChange={setAuthOpen} defaultTab="signin" />
241→    </SidebarProvider>
242→  );
243→};
244→
245→export default Index;
246→

 1→import { Card, CardContent } from "@/components/ui/card";
 2→import { Target, ShieldCheck, BarChart3, TrendingUp } from "lucide-react";
 3→import type { Result } from "@/pages/Index";
 4→
 5→interface ScoreSummaryCardsProps {
 6→  results: Result[];
 7→}
 8→
 9→const ScoreSummaryCards = ({ results }: ScoreSummaryCardsProps) => {
10→  const scored = results.filter((r) => !r.pending && r.overall_score > 0);
11→  if (scored.length === 0) return null;
12→
13→  const avg = (fn: (r: Result) => number) =>
14→    Math.round(scored.reduce((sum, r) => sum + fn(r), 0) / scored.length);
15→
16→  // Compute avg category score from category_scores_json (the actual dynamic scores)
17→  const avgCategoryScore = (r: Result): number => {
18→    if (!r.category_scores_json || typeof r.category_scores_json !== "object") return 0;
19→    const entries = Object.values(r.category_scores_json as Record<string, { score: number }>);
20→    if (entries.length === 0) return 0;
21→    return entries.reduce((sum, e) => sum + (e.score ?? 0), 0) / entries.length;
22→  };
23→
24→  // Compute JD match % from matched vs total must-haves
25→  const jdMatchPercent = (r: Result): number => {
26→    const matched = Array.isArray(r.matched_must_haves) ? r.matched_must_haves.length : 0;
27→    const missing = Array.isArray(r.missing_must_haves) ? r.missing_must_haves.length : 0;
28→    const total = matched + missing;
29→    if (total === 0) return 0;
30→    return Math.round((matched / total) * 100);
31→  };
32→
33→  const cards = [
34→    {
35→      label: "Overall Match",
36→      value: avg((r) => r.overall_score),
37→      icon: Target,
38→      color: "bg-score-overall",
39→      textColor: "text-score-overall",
40→      bgLight: "bg-score-overall/10",
41→    },
42→    {
43→      label: "Avg Skill Score",
44→      value: avg(avgCategoryScore),
45→      icon: BarChart3,
46→      color: "bg-score-skills",
47→      textColor: "text-score-skills",
48→      bgLight: "bg-score-skills/10",
49→    },
50→    {
51→      label: "Confidence",
52→      value: avg((r) => r.confidence ?? 0),
53→      icon: TrendingUp,
54→      color: "bg-score-education",
55→      textColor: "text-score-education",
56→      bgLight: "bg-score-education/10",
57→    },
58→    {
59→      label: "JD Alignment",
60→      value: avg(jdMatchPercent),
61→      icon: ShieldCheck,
62→      color: "bg-score-jd",
63→      textColor: "text-score-jd",
64→      bgLight: "bg-score-jd/10",
65→    },
66→  ];
67→
68→  return (
69→    <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
70→      {cards.map((card) => (
71→        <Card key={card.label} className="overflow-hidden">
72→          <CardContent className="p-4">
73→            <div className="flex items-center gap-2 mb-3">
74→              <div className={`w-8 h-8 rounded-lg ${card.bgLight} flex items-center justify-center`}>
75→                <card.icon className={`h-4 w-4 ${card.textColor}`} />
76→              </div>
77→              <span className="text-xs font-medium text-muted-foreground">{card.label}</span>
78→            </div>
79→            <div className="flex items-end gap-1 mb-2">
80→              <span className={`text-2xl font-bold tabular-nums ${card.textColor}`}>
81→                {card.value}
82→              </span>
83→              <span className="text-sm text-muted-foreground mb-0.5">%</span>
84→            </div>
85→            <div className="h-1.5 rounded-full bg-secondary overflow-hidden">
86→              <div
87→                className={`h-full rounded-full transition-all duration-500 ${card.color}`}
88→                style={{ width: `${Math.min(card.value, 100)}%` }}
89→              />
90→            </div>
91→          </CardContent>
92→        </Card>
93→      ))}
94→    </div>
95→  );
96→};
97→
98→export default ScoreSummaryCards;
99→

  1→import { useState } from "react";
  2→import { Button } from "@/components/ui/button";
  3→import { Badge } from "@/components/ui/badge";
  4→import { Checkbox } from "@/components/ui/checkbox";
  5→import { TableCell, TableRow } from "@/components/ui/table";
  6→import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
  7→import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
  8→import {
  9→  ChevronDown, ChevronUp, Phone, Mail, MapPin,
 10→  FileText, Archive
 11→} from "lucide-react";
 12→import { toast } from "sonner";
 13→import type { Result } from "@/pages/Index";
 14→import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
 15→
 16→// Sub-components
 17→import CandidateSummary from "@/components/candidate/CandidateSummary";
 18→import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
 19→import ExperiencePanel from "@/components/candidate/ExperiencePanel";
 20→import EducationPanel from "@/components/candidate/EducationPanel";
 21→import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
 22→import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
 23→import AINudgePanel from "@/components/candidate/AINudgePanel";
 24→import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
 25→import StageTracker from "@/components/candidate/StageTracker";
 26→import type { HiringStage } from "@/hooks/useStageTracker";
 27→
 28→interface CandidateRowProps {
 29→  result: Result;
 30→  index: number;
 31→  isExpanded: boolean;
 32→  isSelected: boolean;
 33→  jobTitle?: string | null;
 34→  onToggleRow: (id: string) => void;
 35→  onToggleSelect: (resumeId: string) => void;
 36→  onDownload: (filePath: string, filename: string) => void;
 37→  onDelete: (resumeId: string, filePath: string | null) => void;
 38→  onDismiss: (resumeId: string) => void;
 39→  formatCandidateName: (filename: string) => string;
 40→  currentStage?: HiringStage | null;
 41→  stageUpdatedAt?: string | null;
 42→  onStageChange?: (resumeId: string, stage: HiringStage) => void;
 43→}
 44→
 45→const getScoreColor = (score: number) => {
 46→  if (score >= 70) return "bg-score-skills";
 47→  if (score >= 40) return "bg-warning";
 48→  return "bg-destructive";
 49→};
 50→
 51→const getScoreTextColor = (score: number) => {
 52→  if (score >= 70) return "text-score-skills";
 53→  if (score >= 40) return "text-warning";
 54→  return "text-destructive";
 55→};
 56→
 57→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
 58→  if (score >= 70) return { label: "Strong", variant: "success" };
 59→  if (score >= 40) return { label: "Good", variant: "warning" };
 60→  return { label: "Weak", variant: "destructive" };
 61→};
 62→
 63→const getRankDisplay = (index: number) => {
 64→  if (index < 3) {
 65→    const colors = [
 66→      "bg-score-overall text-white",
 67→      "bg-muted-foreground/60 text-white",
 68→      "bg-warning text-white",
 69→    ];
 70→    return (
 71→      <span className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold ${colors[index]}`}>
 72→        {index + 1}
 73→      </span>
 74→    );
 75→  }
 76→  return (
 77→    <span className="inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-medium bg-muted text-muted-foreground">
 78→      {index + 1}
 79→    </span>
 80→  );
 81→};
 82→
 83→const CandidateRow = ({
 84→  result: r,
 85→  index,
 86→  isExpanded,
 87→  isSelected,
 88→  jobTitle,
 89→  onToggleRow,
 90→  onToggleSelect,
 91→  onDownload,
 92→  onDelete,
 93→  onDismiss,
 94→  formatCandidateName,
 95→  currentStage,
 96→  stageUpdatedAt,
 97→  onStageChange,
 98→}: CandidateRowProps) => {
 99→  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
100→  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;
101→
102→  return (
103→    <>
104→    <Collapsible open={isExpanded} onOpenChange={() => onToggleRow(r.id)} asChild>
105→      <>
106→        {/* Collapsed Row */}
107→        <TableRow className="cursor-pointer hover:bg-muted/50 transition-colors" onClick={() => !r.pending && onToggleRow(r.id)}>
108→          <TableCell onClick={(e) => e.stopPropagation()}>
109→            <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
110→          </TableCell>
111→          <TableCell className="text-center">
112→            {r.pending ? <span className="text-sm text-muted-foreground">—</span> : getRankDisplay(index)}
113→          </TableCell>
114→          <TableCell className="font-medium">
115→            <div className="flex flex-col">
116→              <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
117→              {r.candidate_location && (
118→                <span className="flex items-center gap-1 text-xs text-muted-foreground mt-0.5">
119→                  <MapPin className="h-3 w-3" /> {r.candidate_location}
120→                </span>
121→              )}
122→            </div>
123→          </TableCell>
124→          <TableCell>
125→            {r.pending ? (
126→              <Badge variant="outline" className="text-xs">Pending</Badge>
127→            ) : (
128→              <div className="flex items-center gap-2">
129→                <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
130→                  <div
131→                    className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
132→                    style={{ width: `${Math.min(r.overall_score, 100)}%` }}
133→                  />
134→                </div>
135→                <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
136→                  {r.overall_score?.toFixed(0)}%
137→                </span>
138→              </div>
139→            )}
140→          </TableCell>
141→          <TableCell>
142→            <div className="flex flex-wrap items-center gap-1">
143→              {!r.pending && strength && (
144→                <Badge variant={strength.variant} className="text-[10px]">
145→                  {strength.label}
146→                </Badge>
147→              )}
148→              {!r.pending && currentStage && currentStage !== "applied" && (
149→                <Badge variant="outline" className="text-[10px] capitalize">
150→                  {currentStage}
151→                </Badge>
152→              )}
153→              {!r.pending && r.scoring_version === "heuristic" && (
154→                <TooltipProvider delayDuration={300}>
155→                  <Tooltip>
156→                    <TooltipTrigger asChild>
157→                      <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium cursor-default">
158→                        Quick
159→                      </span>
160→                    </TooltipTrigger>
161→                    <TooltipContent className="max-w-xs text-xs">
162→                      This candidate was ranked by keyword matching. Top 20 candidates receive full AI scoring.
163→                    </TooltipContent>
164→                  </Tooltip>
165→                </TooltipProvider>
166→              )}
167→            </div>
168→          </TableCell>
169→          <TableCell>
170→            <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
171→              <TooltipProvider delayDuration={300}>
172→                {/* Phone */}
173→                <Tooltip>
174→                  <TooltipTrigger asChild>
175→                    {r.candidate_phone ? (
176→                      <a
177→                        href={`tel:${r.candidate_phone}`}
178→                        onClick={(e) => {
179→                          if (!/Mobi|Android/i.test(navigator.userAgent)) {
180→                            e.preventDefault();
181→                            navigator.clipboard.writeText(r.candidate_phone!);
182→                            toast.success("Phone number copied!");
183→                          }
184→                        }}
185→                      >
186→                        <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary">
187→                          <Phone className="h-3.5 w-3.5" />
188→                        </Button>
189→                      </a>
190→                    ) : (
191→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
192→                        <Phone className="h-3.5 w-3.5" />
193→                      </Button>
194→                    )}
195→                  </TooltipTrigger>
196→                  <TooltipContent>{r.candidate_phone ? (/Mobi|Android/i.test(navigator.userAgent) ? r.candidate_phone : "Copy phone") : "No phone"}</TooltipContent>
197→                </Tooltip>
198→
199→                {/* Email */}
200→                <Tooltip>
201→                  <TooltipTrigger asChild>
202→                    {r.candidate_email ? (
203→                      <Button
204→                        variant="ghost"
205→                        size="icon"
206→                        className="h-7 w-7 text-muted-foreground hover:text-primary"
207→                        onClick={() => setEmailDialogOpen(true)}
208→                      >
209→                        <Mail className="h-3.5 w-3.5" />
210→                      </Button>
211→                    ) : (
212→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
213→                        <Mail className="h-3.5 w-3.5" />
214→                      </Button>
215→                    )}
216→                  </TooltipTrigger>
217→                  <TooltipContent>{r.candidate_email || "No email"}</TooltipContent>
218→                </Tooltip>
219→
220→                {/* Download */}
221→                <Tooltip>
222→                  <TooltipTrigger asChild>
223→                    {r.file_path ? (
224→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" onClick={() => onDownload(r.file_path!, r.filename)}>
225→                        <FileText className="h-3.5 w-3.5" />
226→                      </Button>
227→                    ) : (
228→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
229→                        <FileText className="h-3.5 w-3.5" />
230→                      </Button>
